package help

import (
	"html"
	"regexp"
	"strings"
	"unicode/utf8"
)

// Prepare turns the website-only syntax of a guide page into plain
// Markdown that the terminal renderer (internal/mdview) draws well:
//
//   - YAML front matter and the "Generated by" comment line are dropped;
//   - admonitions (!!! tip "Title", ??? note, ???+) become a quote with
//     a bold "Tip — Title" line;
//   - tabbed blocks (=== "Tab") become a bold "Tab" line and the body;
//   - attribute lists ({ .md-button }, {: #id }) and icon shortcodes
//     (:material-…:) are removed;
//   - <div markdown> wrappers are dropped, simple inline tags (<p>,
//     <strong>, <span>, <small>) are stripped and their text kept;
//   - ++ctrl+p++ keys become `Ctrl+P`;
//   - C0 / C1 control bytes are removed (tab and newline stay).
//
// Fenced code is never changed. The work is line based.
func Prepare(src string) string {
	src = stripControls(src)
	lines := strings.Split(src, "\n")
	lines = dropFrontMatter(lines)
	return strings.Join(prepareLines(lines), "\n")
}

func stripControls(s string) string {
	clean := true
	for _, r := range s {
		if isControl(r) {
			clean = false
			break
		}
	}
	if clean {
		return s
	}
	return strings.Map(func(r rune) rune {
		if isControl(r) {
			return -1
		}
		return r
	}, s)
}

func isControl(r rune) bool {
	return (r < 0x20 && r != '\t' && r != '\n') || r == 0x7f || (r >= 0x80 && r <= 0x9f) || r == utf8.RuneError
}

// dropFrontMatter removes a leading "---" … "---" YAML block.
func dropFrontMatter(lines []string) []string {
	if len(lines) == 0 || strings.TrimRight(lines[0], " ") != "---" {
		return lines
	}
	for i := 1; i < len(lines); i++ {
		if strings.TrimRight(lines[i], " ") == "---" {
			return lines[i+1:]
		}
		if !strings.Contains(lines[i], ":") && !strings.HasPrefix(strings.TrimSpace(lines[i]), "- ") && strings.TrimSpace(lines[i]) != "" {
			return lines // not YAML: a thematic break at the top
		}
	}
	return lines
}

var (
	reAdmon  = regexp.MustCompile(`^(\s*)(?:!!!|\?\?\?\+?)\s+([\w-]+)(?:\s+"(.*)")?\s*$`)
	reTab    = regexp.MustCompile(`^(\s*)===\+?\s+"(.*)"\s*$`)
	reFence  = regexp.MustCompile("^\\s*(```+|~~~+)")
	reAttr   = regexp.MustCompile(`\{\s*:?\s*[.#][^{}]*\}`)
	reIcon   = regexp.MustCompile(`:(?:material|fontawesome|octicons|simple)-[\w-]+:\s?`)
	reTag    = regexp.MustCompile(`</?(?:div|p|span|strong|b|em|i|small|br)\b[^>]*>`)
	reKeys   = regexp.MustCompile(`\+\+([\w+-]+)\+\+`)
	reSpaces = regexp.MustCompile(`  +`)
	reWrap   = regexp.MustCompile(`^\s*(?:<div\b[^>]*>|</div>)\s*$`)
	reStat   = regexp.MustCompile(`^\s*<div\b[^>]*>(.*)</div>\s*$`)
)

func prepareLines(lines []string) []string {
	out := make([]string, 0, len(lines))
	fence := ""
	for i := 0; i < len(lines); i++ {
		l := lines[i]
		if fence != "" { // inside fenced code: as is
			out = append(out, l)
			if m := reFence.FindStringSubmatch(l); m != nil && strings.HasPrefix(m[1], fence) && strings.TrimSpace(l) == m[1] {
				fence = ""
			}
			continue
		}
		if m := reFence.FindStringSubmatch(l); m != nil {
			fence = m[1]
			out = append(out, l)
			continue
		}
		if m := reAdmon.FindStringSubmatch(l); m != nil {
			body, next := block(lines, i+1, len(m[1])+4)
			head := strings.ToUpper(m[2][:1]) + m[2][1:]
			if m[3] != "" {
				head += " — " + m[3]
			}
			out = append(out, m[1]+"> **"+head+"**", m[1]+">")
			for _, b := range prepareLines(body) {
				if b == "" {
					out = append(out, m[1]+">")
				} else {
					out = append(out, m[1]+"> "+b)
				}
			}
			if next < len(lines) && strings.TrimSpace(lines[next]) != "" {
				out = append(out, "") // the next line must not join the quote
			}
			i = next - 1
			continue
		}
		if m := reTab.FindStringSubmatch(l); m != nil {
			body, next := block(lines, i+1, len(m[1])+4)
			out = append(out, m[1]+"**"+m[2]+"**", "")
			for _, b := range prepareLines(body) {
				if b == "" {
					out = append(out, "")
				} else {
					out = append(out, m[1]+b)
				}
			}
			if next < len(lines) && strings.TrimSpace(lines[next]) != "" {
				out = append(out, "")
			}
			i = next - 1
			continue
		}
		t := strings.TrimSpace(l)
		if strings.HasPrefix(t, "<!--") && strings.HasSuffix(t, "-->") && strings.Contains(t, "Generated by") {
			continue
		}
		if reWrap.MatchString(l) {
			out = append(out, "")
			continue
		}
		if m := reStat.FindStringSubmatch(l); m != nil { // <div markdown>…</div> on one line
			out = append(out, "- "+strings.TrimSpace(inlineLine(m[1])))
			continue
		}
		out = append(out, inlineLine(l))
	}
	return out
}

// block collects the indented body that starts at lines[from]: blank
// lines and lines indented by at least ind. Trailing blank lines are not
// part of it. The body comes back dedented by ind.
func block(lines []string, from, ind int) (body []string, next int) {
	end := from
	for j := from; j < len(lines); j++ {
		l := lines[j]
		if strings.TrimSpace(l) == "" {
			continue
		}
		if indentOf(l) < ind {
			break
		}
		end = j + 1
	}
	for j := from; j < end; j++ {
		body = append(body, dedent(lines[j], ind))
	}
	return body, end
}

// indentOf is the width of the leading white space (a tab counts 4).
func indentOf(l string) int {
	n := 0
	for _, c := range l {
		switch c {
		case ' ':
			n++
		case '\t':
			n += 4 - n%4
		default:
			return n
		}
	}
	return n
}

func dedent(l string, n int) string {
	if strings.TrimSpace(l) == "" {
		return ""
	}
	l = strings.Replace(l, "\t", "    ", 1)
	w := 0
	for w < len(l) && w < n && l[w] == ' ' {
		w++
	}
	return l[w:]
}

// inlineLine cleans one line outside fenced code. Code spans are kept
// as written.
func inlineLine(l string) string {
	parts := splitCode(l)
	changed := false
	for k := 0; k < len(parts); k += 2 { // even parts are outside code spans
		p := parts[k]
		q := reIcon.ReplaceAllString(p, "")
		q = reAttr.ReplaceAllString(q, "")
		q = reKeys.ReplaceAllStringFunc(q, func(s string) string {
			keys := strings.Split(strings.Trim(s, "+"), "+")
			for i, k := range keys {
				if k != "" {
					keys[i] = strings.ToUpper(k[:1]) + k[1:]
				}
			}
			return "`" + strings.Join(keys, "+") + "`"
		})
		if reTag.MatchString(q) {
			q = reTag.ReplaceAllStringFunc(q, func(tag string) string {
				name := strings.ToLower(strings.TrimLeft(strings.Fields(strings.Trim(tag, "<>"))[0], "/"))
				switch name {
				case "strong", "b":
					return "**"
				case "em", "i":
					return "*"
				case "span", "br":
					if !strings.HasPrefix(tag, "</") {
						return " "
					}
				}
				return ""
			})
			q = html.UnescapeString(q)
		}
		if q != p {
			changed = true
			parts[k] = q
		}
	}
	if !changed {
		return l
	}
	lead := len(l) - len(strings.TrimLeft(l, " \t"))
	s := strings.Join(parts, "")
	if lead > len(s) {
		lead = 0
	}
	// Removed pieces leave double spaces; collapse them after the indent
	// (a list marker's spacing included: "-   **A**" → "- **A**").
	return strings.TrimRight(s[:lead]+reSpaces.ReplaceAllString(s[lead:], " "), " ")
}

// splitCode splits a line at code spans: even items are text, odd items
// are code spans with their backticks.
func splitCode(l string) []string {
	var out []string
	for {
		i := strings.IndexByte(l, '`')
		if i < 0 {
			return append(out, l)
		}
		n := 0
		for i+n < len(l) && l[i+n] == '`' {
			n++
		}
		tick := l[i : i+n]
		j := strings.Index(l[i+n:], tick)
		if j < 0 {
			return append(out, l)
		}
		end := i + n + j + n
		out = append(out, l[:i], l[i:end])
		l = l[end:]
	}
}
